import GameUI from './components/GameUI';

/**
 * Root component for the 3D 8-Ball Pool Game.
 *
 * Architecture:
 *   App
 *   ├── Scene (R3F Canvas)
 *   │   ├── PhysicsWorld
 *   │   ├── Table
 *   │   ├── Balls (16x BallBody + Ball mesh)
 *   │   ├── CueStick
 *   │   └── AimLine
 *   └── GameUI (HTML overlay)
 */
function App() {
  return (
    <div
      style={{
        width: '100vw',
        height: '100vh',
        background: '#1a1a2e',
        overflow: 'hidden',
      }}
    >
      <Scene />
      <GameUI />
    </div>
  );
}

export default App;","end_line":32,"start_line":0,"total_lines":33}

