{"content":"import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import Table from './Table';
import Balls from './Balls';
import PhysicsWorld from '../physics/PhysicsWorld';
import CueStick from './CueStick';
import AimLine from './AimLine';
import { CAMERA_DEFAULT_POSITION, CAMERA_FOV } from '../constants/table';
import useShotSequence from '../hooks/useShotSequence';
import useSettleDetector from '../hooks/useSettleDetector';

export default function Scene() {
  return (
    <Canvas
      shadows
      camera={{
        position: CAMERA_DEFAULT_POSITION,
        fov: CAMERA_FOV,
        near: 0.1,
        far: 50,
      }}
      style={{ width: '100%', height: '100%' }}
    >
      <color attach="background" args={['#1a1a2e']} />
      <fog attach="fog" args={['#1a1a2e', 5, 15]} />

      {/* Lighting */}
      <ambientLight intensity={0.3} />
      <directionalLight
        position={[0, 3, 0]}
        intensity={1.2}
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-camera-far={10}
        shadow-camera-left={-2}
        shadow-camera-right={2}
        shadow-camera-top={2}
        shadow-camera-bottom={-2}
      />
      <pointLight position={[-0.5, 2, -0.8]} intensity={0.4} color="#fff5e6" />
      <pointLight position={[0.5, 2, 0.8]} intensity={0.4} color="#fff5e6" />

      <PhysicsWorld>
        <Table />
        <Balls />
        <CueStick />
        <AimLine />
        <GameHooks />
      </PhysicsWorld>

      <OrbitControls
        enablePan={false}
        minPolarAngle={0.2}
        maxPolarAngle={Math.PI / 2.2}
        minDistance={1}
        maxDistance={5}
        target={[0, 0, 0]}
      />

      {/* Floor */}
      <mesh
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, -0.8, 0]}
        receiveShadow
      >
        <planeGeometry args={[20, 20]} />
        <meshStandardMaterial color="#1a0f0a" />
      </mesh>
    </Canvas>
  );
}

/**
 * Wrapper component for hooks that need to be inside the Canvas/Physics context
 */
function GameHooks() {
  useSettleDetector();
  useShotSequence();
  return null;
}","end_line":80,"start_line":0,"total_lines":81}

{"content":"import { useMemo } from 'react';
import * as THREE from 'three';
import {
  TABLE_LENGTH,
  TABLE_WIDTH,
  TABLE_HEIGHT,
  RAIL_HEIGHT,
  RAIL_WIDTH,
  HALF_LENGTH,
  HALF_WIDTH,
  POCKET_POSITIONS,
  CUSHION_THICKNESS,
  BALL_RADIUS,
} from '../constants/table';
import { generateFeltTexture, generateWoodTexture } from '../utils/textures';

export default function Table() {
  const feltTexture = useMemo(() => {
    const canvas = generateFeltTexture();
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(4, 8);
    return tex;
  }, []);

  const woodTexture = useMemo(() => {
    const canvas = generateWoodTexture();
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    return tex;
  }, []);

  const railLength = (HALF_WIDTH - POCKET_POSITIONS[4][0]) * 2 - RAIL_WIDTH * 2;

  return (
    <group>
      {/* Table bed (felt surface) */}
      <mesh position={[0, -TABLE_HEIGHT / 2, 0]} receiveShadow>
        <boxGeometry args={[TABLE_WIDTH + RAIL_WIDTH * 2, TABLE_HEIGHT, TABLE_LENGTH + RAIL_WIDTH * 2]} />
        <meshStandardMaterial map={feltTexture} color="#0d6b2e" />
      </mesh>

      {/* Playing surface (thin felt layer on top) */}
      <mesh position={[0, 0, 0]} receiveShadow>
        <boxGeometry args={[TABLE_WIDTH, 0.001, TABLE_LENGTH]} />
        <meshStandardMaterial color="#0d6b2e" map={feltTexture} />
      </mesh>

      {/* Rails - Long sides (left and right) */}
      {/* Left rail - two segments (pocket gaps at middle and corners) */}
      <RailSegment
        position={[-HALF_WIDTH - RAIL_WIDTH / 2, RAIL_HEIGHT / 2, -HALF_LENGTH / 2 - RAIL_WIDTH / 4]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, HALF_LENGTH - RAIL_WIDTH]}
        texture={woodTexture}
      />
      <RailSegment
        position={[-HALF_WIDTH - RAIL_WIDTH / 2, RAIL_HEIGHT / 2, HALF_LENGTH / 2 + RAIL_WIDTH / 4]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, HALF_LENGTH - RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* Right rail - two segments */}
      <RailSegment
        position={[HALF_WIDTH + RAIL_WIDTH / 2, RAIL_HEIGHT / 2, -HALF_LENGTH / 2 - RAIL_WIDTH / 4]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, HALF_LENGTH - RAIL_WIDTH]}
        texture={woodTexture}
      />
      <RailSegment
        position={[HALF_WIDTH + RAIL_WIDTH / 2, RAIL_HEIGHT / 2, HALF_LENGTH / 2 + RAIL_WIDTH / 4]}
        size={[RAIL_WIDTH, RAIL_HEIGHT, HALF_LENGTH - RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* End rails (top and bottom) */}
      <RailSegment
        position={[0, RAIL_HEIGHT / 2, -HALF_LENGTH - RAIL_WIDTH / 2]}
        size={[TABLE_WIDTH, RAIL_HEIGHT, RAIL_WIDTH]}
        texture={woodTexture}
      />
      <RailSegment
        position={[0, RAIL_HEIGHT / 2, HALF_LENGTH + RAIL_WIDTH / 2]}
        size={[TABLE_WIDTH, RAIL_HEIGHT, RAIL_WIDTH]}
        texture={woodTexture}
      />

      {/* Cushions (inner bumpers) - simplified as boxes along edges */}
      {/* Top cushion (left half) */}
      <Cushion
        position={[-HALF_WIDTH / 2, BALL_RADIUS * 0.6, -HALF_LENGTH + CUSHION_THICKNESS / 2]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.5, BALL_RADIUS * 1.2, CUSHION_THICKNESS]}
      />
      {/* Top cushion (right half) */}
      <Cushion
        position={[HALF_WIDTH / 2, BALL_RADIUS * 0.6, -HALF_LENGTH + CUSHION_THICKNESS / 2]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.5, BALL_RADIUS * 1.2, CUSHION_THICKNESS]}
      />
      {/* Bottom cushion (left half) */}
      <Cushion
        position={[-HALF_WIDTH / 2, BALL_RADIUS * 0.6, HALF_LENGTH - CUSHION_THICKNESS / 2]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.5, BALL_RADIUS * 1.2, CUSHION_THICKNESS]}
      />
      {/* Bottom cushion (right half) */}
      <Cushion
        position={[HALF_WIDTH / 2, BALL_RADIUS * 0.6, HALF_LENGTH - CUSHION_THICKNESS / 2]}
        size={[HALF_WIDTH - RAIL_WIDTH * 1.5, BALL_RADIUS * 1.2, CUSHION_THICKNESS]}
      />
      {/* Left cushion */}
      <Cushion
        position={[-HALF_WIDTH + CUSHION_THICKNESS / 2, BALL_RADIUS * 0.6, 0]}
        size={[CUSHION_THICKNESS, BALL_RADIUS * 1.2, TABLE_LENGTH - RAIL_WIDTH * 3]}
      />
      {/* Right cushion */}
      <Cushion
        position={[HALF_WIDTH - CUSHION_THICKNESS / 2, BALL_RADIUS * 0.6, 0]}
        size={[CUSHION_THICKNESS, BALL_RADIUS * 1.2, TABLE_LENGTH - RAIL_WIDTH * 3]}
      />

      {/* Pockets */}
      {POCKET_POSITIONS.map((pos, i) => (
        <mesh key={i} position={[pos[0], -0.005, pos[2]]} rotation={[-Math.PI / 2, 0, 0]}>
          <circleGeometry args={[0.047, 32]} />
          <meshStandardMaterial color="#0a0a0a" />
        </mesh>
      ))}
    </group>
  );
}

function RailSegment({
  position,
  size,
  texture,
}: {
  position: [number, number, number];
  size: [number, number, number];
  texture: THREE.Texture;
}) {
  return (
    <mesh position={position} castShadow receiveShadow>
      <boxGeometry args={size} />
      <meshStandardMaterial map={texture} color="#5C3317" />
    </mesh>
  );
}

function Cushion({
  position,
  size,
}: {
  position: [number, number, number];
  size: [number, number, number];
}) {
  return (
    <mesh position={position}>
      <boxGeometry args={size} />
      <meshStandardMaterial color="#0a8a3a" />
    </mesh>
  );
}","end_line":158,"start_line":0,"total_lines":159}

{"content":"import { useRef, useMemo } from 'react';
import * as THREE from 'three';
import type { BallId } from '../types';
import { BALL_RADIUS } from '../constants/table';
import { generateBallTexture } from '../utils/textures';

interface BallProps {
  id: BallId;
  position: [number, number, number];
  api?: { position: any; velocity: any; angularVelocity: any };
}

export default function Ball({ id, position: initialPos, api }: BallProps) {
  const meshRef = useRef<THREE.Mesh>(null);

  const texture = useMemo(() => {
    const canvas = generateBallTexture(id);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
  }, [id]);

  // Subscribe to physics position updates
  if (api && meshRef.current) {
    api.position.subscribe((pos: [number, number, number]) => {
      if (meshRef.current) {
        meshRef.current.position.set(pos[0], pos[1], pos[2]);
      }
    });
  }

  return (
    <mesh
      ref={meshRef}
      position={initialPos}
      castShadow
      receiveShadow
    >
      <sphereGeometry args={[BALL_RADIUS, 32, 32]} />
      <meshStandardMaterial
        map={texture}
        roughness={0.2}
        metalness={0.05}
      />
    </mesh>
  );
}","end_line":46,"start_line":0,"total_lines":47}

